def _archivos_cortos_enteros(pedazos, codigo):
    """Si el archivo de un pedazo tiene 600 renglones o menos, se entrega ENTERO.

    Julio, 2026-09-21. Motivo medido el 2026-09-20: tres rondas pagadas se perdieron porque al
    obrero le llegaron trozos sueltos de archivos cortos y contesto que no encontraba lo que
    tenia que cambiar; un archivo de 255 renglones ocupa muy poco y cabe de sobra.
    Los archivos mas largos siguen exactamente igual que hoy.
    """
    if not pedazos:
        return pedazos
    por_id = {}
    for p in (codigo or []):
        por_id[p.get("id")] = p
    salida, ya_entero = [], set()
    for t in pedazos:
        pieza = por_id.get(t.get("pieza"))
        abs_path = (pieza or {}).get("abs") or t.get("abs")
        if not abs_path or not str(abs_path).lower().endswith(".py"):
            salida.append(t)
            continue
        lineas = (pieza or {}).get("lineas") or 0
        if not lineas:
            try:
                lineas = len(_lineas_de(abs_path, 1, 10 ** 9))
            except Exception:
                lineas = 0
        if lineas <= 0 or lineas > 600:
            salida.append(t)
            continue
        marca = t.get("pieza")
        if marca in ya_entero:
            continue
        ya_entero.add(marca)
        try:
            texto = "\n".join(_lineas_de(abs_path, 1, lineas))
        except Exception:
            salida.append(t)
            continue
        nuevo = dict(t)
        nuevo.update({"desde": 1, "hasta": lineas, "texto": texto,
                      "direccion": "%s:1-%s" % (t.get("pieza"), lineas),
                      "_completo": "archivo_corto"})
        salida.append(nuevo)
    return salida
